/* ==== Exact Horror Background - Fade In Deluxe ==== */
@-moz-document domain("roblox.com"), url-prefix("https://www.roblox.com") {
body {
    background: url("https://chatgpt.com/backend-api/estuary/content?id=file_000000003cb871f58495a435f535f24c&ts=489504&p=fs&cid=1&sig=3b8680d42f8b8e36429efa0e79f3467e95e8984a78d5ce4d4bd4cd43704ecc3b&v=0")
      no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
    font-family: 'Poppins', sans-serif !important;
    animation: fadeInBackground 3s ease-in-out forwards;
    opacity: 0;
  }

  @keyframes fadeInBackground {
    0% { opacity: 0; filter: brightness(0.4) blur(3px); }
    100% { opacity: 1; filter: brightness(1) blur(0); }
  }

  /* Transparent glassy panels for readability */
  .content, .container, .navbar, .footer, .header, .main-content {
    background: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(8px) brightness(0.8);
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    color: #fff !important;
    transition: all 0.4s ease-in-out !important;
  }

  /* Text Glow + Subtle Hover Lighting */
  h1, h2, h3, h4, h5, h6, p, a, span, label {
    color: #f8f8f8 !important;
    text-shadow: 0 0 6px rgba(255, 255, 255, 0.2);
  }

  a:hover {
    color: #ffffff !important;
    text-shadow: 0 0 12px #ffffff90;
  }

  /* Buttons */
  button, .btn, input[type="submit"], input[type="button"] {
    background: rgba(20, 20, 20, 0.8) !important;
    color: #fff !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.8);
    transition: all 0.3s ease-in-out !important;
  }

  button:hover, .btn:hover {
    background: rgba(255, 255, 255, 0.1) !important;
    box-shadow: 0 0 15px rgba(255,255,255,0.3);
    transform: scale(1.05);
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
    background-color: #000;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #222, #444);
    border-radius: 6px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #555, #777);
  }

  /* Slight dark vignette around edges for atmosphere */
  body::after {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    box-shadow: inset 0 0 200px rgba(0,0,0,0.8);
    pointer-events: none;
    z-index: 9999;
  }
}
